--
-- Table structure for table `bantuan_pkh`
--

DROP TABLE IF EXISTS `bantuan_pkh`;
/*!40101 SET @saved_cs_client = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `bantuan_pkh`
(
    `id`               bigint(20) unsigned NOT NULL AUTO_INCREMENT,
    `dtks_id`          char(36)            NOT NULL DEFAULT '10063040-43f6-4fe3-927d-4b6c2afec4dc',
    `nokk`             varchar(255)        NOT NULL,
    `nik_ktp`          varchar(255)        NOT NULL,
    `nama_penerima`    varchar(255)        NOT NULL,
    `kode_wilayah`     char(10)            NOT NULL,
    `tahap`            tinyint(3) unsigned NOT NULL,
    `bansos`           varchar(255)        NOT NULL,
    `jenis_bantuan_id` bigint(20) unsigned          DEFAULT 1,
    `nominal`          double(20, 2) unsigned       DEFAULT 0.00,
    `bank`             varchar(255)        NOT NULL,
    `provinsi`         char(2)                      DEFAULT NULL,
    `kabupaten`        char(7)                      DEFAULT NULL,
    `kecamatan`        char(10)                     DEFAULT NULL,
    `kelurahan`        char(15)                     DEFAULT NULL,
    `alamat`           varchar(255)        NOT NULL,
    `no_rt`            varchar(255)                 DEFAULT NULL,
    `no_rw`            varchar(255)                 DEFAULT NULL,
    `dusun`            varchar(255)                 DEFAULT NULL,
    `dir`              varchar(255)                 DEFAULT NULL,
    `gelombang`        varchar(255)                 DEFAULT NULL,
    `tahun`            year(4)                      DEFAULT NULL,
    `status_pkh`       varchar(255)                 DEFAULT 'PKH',
    `status_dtks`      varchar(30)                  DEFAULT 'DTKS',
    `deleted_at`       timestamp           NULL     DEFAULT NULL,
    `created_at`       timestamp           NULL     DEFAULT NULL,
    `updated_at`       timestamp           NULL     DEFAULT NULL,
    PRIMARY KEY (`id`) USING BTREE,
    UNIQUE KEY `id` (`id`) USING BTREE,
    KEY `bantuan_pkh_jenis_bantuan_id_foreign` (`jenis_bantuan_id`) USING BTREE,
    KEY `nokk` (`nokk`, `nik_ktp`, `nama_penerima`) USING BTREE,
    KEY `alamat` (`alamat`) USING BTREE,
    KEY `provinsi` (`provinsi`, `kabupaten`, `kecamatan`, `kelurahan`) USING BTREE,
    CONSTRAINT `bantuan_pkh_jenis_bantuan_id_foreign` FOREIGN KEY (`jenis_bantuan_id`) REFERENCES `jenis_bantuan` (`id`) ON UPDATE CASCADE
) ENGINE = InnoDB
  AUTO_INCREMENT = 10601
  DEFAULT CHARSET = utf8mb4
  COLLATE = utf8mb4_unicode_ci
  ROW_FORMAT = DYNAMIC;
/*!40101 SET character_set_client = @saved_cs_client */;

